const f = reformer.form();
f.title("Оформление заказа");
f.field("customerType").label("Тип покупателя").options([{value:"person",label:"Физическое лицо"},{value:"company",label:"Юридическое лицо"}]).required("Выберите тип покупателя");
f.field("contact.lastName").label("Фамилия").required("Введите фамилию").minLength(2,"Минимум 2 символа");
f.field("contact.firstName").label("Имя").required("Введите имя").minLength(2,"Минимум 2 символа");
f.field("email").required("Введите email").email("Некорректный email");
f.field("phone").label("Телефон").mask("+7 (999) 999-99-99").required("Введите телефон").pattern(/^\+7 \(\d{3}\) \d{3}-\d{2}-\d{2}$/,"Формат +7 (999) 999-99-99");
f.field("birthDate").label("Дата рождения").type("date").showWhen(m=>m.customerType==="person").required("Укажите дату рождения").when(m=>m.customerType==="person");
f.field("company.name").label("Название организации").showWhen(m=>m.customerType==="company").required("Введите название организации").when(m=>m.customerType==="company");
f.field("company.inn").label("ИНН").showWhen(m=>m.customerType==="company").required("Введите ИНН").pattern(/^\d{10}$/,"ИНН — 10 цифр").when(m=>m.customerType==="company");
f.field("deliveryMethod").label("Способ получения").options([{value:"pickup",label:"Самовывоз"},{value:"courier",label:"Курьер"},{value:"post",label:"Почта"}]).required("Выберите способ получения");
for (const [k,l,msg] of [["city","Город","Введите город"],["street","Улица","Введите улицу"],["house","Дом","Введите дом"]]) {
  f.field("deliveryAddress."+k).label(l).required(msg).when(m=>m.deliveryMethod!=="pickup").disableWhen(m=>m.deliveryMethod==="pickup",{resetOnDisable:true});
  f.field("billingAddress."+k).label(l).required(msg).when(m=>!m.billingSame);
}
f.field("deliveryDate").label("Дата доставки").showWhen(m=>m.deliveryMethod==="courier").required("Выберите дату доставки").future("Дата доставки — не раньше завтрашнего дня").when(m=>m.deliveryMethod==="courier").resetWhen(m=>m.deliveryMethod!=="courier");
f.field("billingSame").label("Адрес для счёта совпадает с адресом доставки");
f.field("subtotal").label("Сумма товаров").readonly().compute(m=>m.items.reduce((s,r)=>s+(Number(r.quantity)||0)*(Number(r.price)||0),0));
f.field("promoCode").label("Промокод").transform(v=>String(v).toUpperCase()).asyncCheck(v=>!v||v==="SALE10"||v==="SALE20",{delay:300,message:"Промокод не найден"});
f.field("discount").label("Скидка, %").min(0,"Скидка не может быть отрицательной").max(30,"Скидка не больше 30%").enableWhen(m=>m.customerType==="company",{resetOnDisable:true});
f.field("total").label("Итого").readonly().compute(m=>Math.round(m.subtotal*(1-m.discount/100)*100)/100).warning(m=>m.total<=100000,"Крупный заказ: менеджер свяжется для подтверждения");
f.field("paymentMethod").label("Способ оплаты").options([{value:"card",label:"Картой онлайн"},{value:"cash",label:"При получении"},{value:"invoice",label:"По счёту"}]).required("Выберите способ оплаты").check(m=>m.paymentMethod!=="invoice"||m.customerType==="company","Оплата по счёту — только для юридических лиц").setOnChange("customerType",m=>m.customerType==="person"&&m.paymentMethod==="invoice","card");
f.field("receiptEmail").label("Email для чека").email("Некорректный email для чека").sync("email");
f.field("comment").label("Комментарий к заказу").maxLength(500,"Не больше 500 символов");
f.field("agreeTerms").label("Согласен с условиями оферты").required("Нужно принять условия оферты");
f.field("newsletter").label("Получать новости и акции");
f.field("sources").label("Как вы о нас узнали").options([{value:"search",label:"Поиск"},{value:"friends",label:"Друзья"},{value:"ads",label:"Реклама"},{value:"other",label:"Другое"}]);
const it=f.array("items","Товары",{min:1,max:10});
it.min(1,"Добавьте хотя бы один товар");it.max(10,"Не больше 10 товаров");
it.column("title","Наименование").required("Введите наименование");
it.column("quantity","Количество").initial(1).required("Укажите количество").rule("integer()","Количество — целое число").min(1,"Минимум 1").max(99,"Максимум 99");
it.column("price","Цена").required("Укажите цену").min(0,"Цена не может быть отрицательной");
it.column("lineTotal","Сумма").readonly().compute(r=>(Number(r.quantity)||0)*(Number(r.price)||0));
const rc=f.array("recipients","Кому отправлять уведомления");
rc.column("email","Email получателя").required("Введите email получателя").email("Некорректный email получателя");
rc.column("primary","Основной получатель").exclusive({first:true});
rc.startRows([{email:"",primary:true}]);
f.submit("Оформить заказ","submitOrder");
console.log(await f.save());

